package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen2Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000755 ".getBytes();
        // length 7, offset 0. end=7. buffer[7] is out of bounds? 
        // Wait, the code uses buffer[end/1]. If length is 7, end is 7. 
        // Let's ensure buffer is large enough to avoid IndexOutOfBounds in the logic.
        byte[] buf = new byte[10];
        System.arraycopy("000755 ".getBytes(), 0, buf, 0, 7);
        assertEquals(493L, TarUtils.parseOctal(buf, 0, 7));
    }

    @Test
    public void testParseOctal_AllNUL() {
        byte[] buffer = new byte[5]; // all zeros
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 5));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooSmall() {
        byte[] buffer = new byte[5];
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        byte[] buf = new byte[10];
        System.arraycopy("   755 ".getBytes(), 0, buf, 0, 7);
        // end = 7. trailer = buffer[7] = ' '. end becomes 6.
        // trailer = buffer[5] = '5'. end stays 6.
        // start skips spaces to index 3. Loop 3 to 6. bytes: 7, 5, 5.
        assertEquals(493L, TarUtils.parseOctal(buf, 0, 7));
    }

    @Test
    public void testParseOctal_WithTrailingNUL() {
        byte[] buf = new byte[10];
        System.arraycopy("755\0".getBytes(), 0, buf, 0, 4);
        // end = 4. trailer = buffer[4] = 0. end becomes 3.
        // trailer = buffer[2] = '5'. end stays 3.
        // start 0 to 3. bytes: 7, 5, 5.
        assertEquals(493L, TarUtils.parseOctal(buf, 0, 4));
    }

    @Test
    public void testParseOctal_WithTrailingSpace() {
        byte[] buf = new byte[10];
        System.arraycopy("755 ".getBytes(), 0, buf, 0, 4);
        assertEquals(493L, TarUtils.parseOctal(buf, 0, 4));
    }

    @Test
    public void testParseOctal_DoubleTrailingNULOrSpace() {
        byte[] buf = new byte[10];
        // Testing the logic where end is decremented twice
        // "755  " (two spaces)
        System.arraycopy("755  ".getBytes(), 0, buf, 0, 5);
        assertEquals(493L, TarUtils.parseOctal(buf, 0, 5));

        // "755\0 " (NUL then space)
        byte[] buf2 = new byte[10];
        System.arraycopy("755\0 ".getBytes(), 0, buf2, 0, 5);
        assertEquals(493L, TarUtils.parseOctal(buf2, 0, 5));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidTrailer() {
        byte[] buf = new byte[10];
        System.arraycopy("755X".getBytes(), 0, buf, 0, 4);
        // end = 4. buffer[4] is 0. So it actually passes the trailer check if buffer is zeroed.
        // To trigger exception, buffer[end] must be something other than 0 or ' '.
        byte[] bufErr = new byte[10];
        System.arraycopy("755".getBytes(), 0, bufErr, 0, 3);
        bufErr[3] = 'X'; 
        TarUtils.parseOctal(bufErr, 0, 3);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        byte[] buf = new byte[10];
        System.arraycopy("785 ".getBytes(), 0, buf, 0, 4);
        // '8' is not octal
        TarUtils.parseOctal(buf, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_NonDigitChar() {
        byte[] buf = new byte[10];
        System.arraycopy("7A5 ".getBytes(), 0, buf, 0, 4);
        TarUtils.parseOctal(buf, 0, 4);
    }

    @Test
    public void testParseOctal_LargeValue() {
        byte[] buf = new byte[20];
        String octal = "7777777777"; // Large octal
        System.arraycopy(octal.getBytes(), 0, buf, 0, octal.length());
        buf[octal.length()] = 0; // trailer
        long expected = Long.parseLong(octal, 8);
        assertEquals(expected, TarUtils.parseOctal(buf, 0, octal.length()));
    }
}
